using UnityEngine;
// Shared 1600x900 layout. Reads existing simulation values without changing rules.
public static class CockpitUI {
 public static float Scale {get{return UiReadability.HudScale(Screen.width,Screen.height);}}
 public static bool LayoutFits(float w,float h){float s=UiReadability.HudScale(w,h);return w/s>=1599.99f&&h/s>=899.99f;}
 public static Rect SpeedBounds(float w,float h){float s=UiReadability.HudScale(w,h);return new Rect(w/2-200*s,h-238*s,400*s,224*s);}
 public static Rect JobBounds(float w,float h,bool active){float s=UiReadability.HudScale(w,h);return new Rect(w-312*s,382*s,288*s,(active?150:58)*s);}
 public static Rect SituationBounds(float w,float h,bool result=false,bool activeJob=true){float s=UiReadability.HudScale(w,h);return new Rect(24*s,414*s,300*s,Mathf.Min((result?118:220)*s,h-260*s-414*s));}
 public static Rect ServiceHintBounds(float w,float h){float s=UiReadability.HudScale(w,h);return new Rect(365*s,210*s,410*s,110*s);}
 public static Rect SlidingTipBounds(float w,float h,bool result,bool active,float visible){var r=SituationBounds(w,h,result,active);r.x=Mathf.Lerp(-r.width,r.x,Mathf.Clamp01(visible));return r;}
 public static string Clock(double seconds){int n=Mathf.CeilToInt((float)System.Math.Max(0,seconds));return n/60+":"+(n%60).ToString("00");}
 static void Label(Rect r,string value,int size=18,Color? color=null,bool bold=false){GUI.Label(r,value,DrivingHudArt.Text(size,color,bold));}
 public static void Draw(DriveHUD hud){
  var s=hud.session;var e=s.business.ledger;var jobs=s.jobs;var match=s.simulationMatch;var previous=GUI.matrix;float scale=Scale;GUI.matrix=Matrix4x4.Scale(new Vector3(scale,scale,1));float w=Screen.width/scale,h=Screen.height/scale;
  DrivingHudArt.Glass(new Rect(24,20,300,92));string region=match?"PVP 도시":MapCatalog.Name(s.world.map.mapId);var regionStyle=DrivingHudArt.Text(14,DrivingHudArt.Light);GUI.Label(new Rect(42,27,264,25),new GUIContent(UiReadability.Ellipsis(region,regionStyle,264),region),regionStyle);
  int minute=480+(int)(e.Elapsed*720/e.Settings.daySeconds);HudGlyph.Draw(new Rect(42,60,28,28),18,DrivingHudArt.Cyan);
