 }
 static void DrawConditions(DriveSession s){
  var e=s.business.ledger;if(e.Driver==null||e.Account==null)return;string[] names={"연료","차량 내구도","청결도","포만감","피로"};float[] values={e.Account.Fuel,e.Care.Damage.Durability,e.Care.Cleanliness,(float)e.Driver.satiety,(float)e.Driver.fatigue};int[] glyphs={8,12,14,9,11};
  for(int i=0;i<5;i++){float y=202+i*35,v=Mathf.Clamp(values[i],0,100);bool warn=i==4?v>=75:i==1?v<=50:i==2?v<30:v<=25;Color color=warn?new Color(1,.54f,.31f):i==4?new Color(.75f,.66f,1):DrivingHudArt.Lime;DrivingHudArt.Glass(new Rect(24,y,300,30));HudGlyph.Draw(new Rect(37,y+5,20,20),glyphs[i],color);Label(new Rect(65,y+1,110,28),names[i],14);DrivingHudArt.Meter(new Rect(177,y+10,74,10),v,color);Label(new Rect(259,y+1,54,28),Mathf.RoundToInt(v).ToString(),15,color,true);}
  string warning=e.Care.Damage.Durability==0?"운행 불가":e.Care.Damage.Durability<=20?"수리 필요":e.Care.Damage.Durability<=50?"수리 권장":"";if(e.Care.Cleanliness<30)warning+=(warning.Length>0?" / ":"")+"세차 필요";if(warning.Length>0){DrivingHudArt.Glass(new Rect(24,378,300,28));Label(new Rect(38,378,274,28),warning,13,new Color(1,.65f,.43f),true);}
 }
 static Vector2 careScroll;static string careIdentity="";static int lastCareFrame=-2;
 public static void DrawCareMessage(Rect r,string message){
  string key=message.Substring(0,Mathf.Min(16,message.Length));if(careIdentity!=key||Time.frameCount>lastCareFrame+1){careIdentity=key;careScroll=Vector2.zero;}lastCareFrame=Time.frameCount;
  var style=new GUIStyle(DrivingHudArt.Text(16,CasualUI.Ink,true)){wordWrap=true};float width=r.width-22,height=style.CalcHeight(new GUIContent(message),width);
  careScroll.y=Mathf.Clamp(careScroll.y,0,Mathf.Max(0,height-r.height));careScroll=GUI.BeginScrollView(r,careScroll,new Rect(0,0,width,Mathf.Max(r.height,height)),false,height>r.height);GUI.Label(new Rect(0,0,width,height),message,style);GUI.EndScrollView();
 }
 static void DrawPassenger(DriveSession s,float h){
