  Label(new Rect(202,y+12,270,26),!string.IsNullOrEmpty(jobs.VisibleCareDialogue)?"승객 안내 · 스크롤":occupied?"함께하는 승객":jobs.Active?"승객을 만나러 가요":"다음 승객을 기다려요",18,null,true);string message=jobs.VisibleCareDialogue;if(string.IsNullOrEmpty(message))message=occupied?"목적지까지 안전하게 모셔 주세요.":jobs.Active?"안내된 승차 장소에서 정차하세요.":"지도에서 새로운 호출을 확인하세요.";CasualUI.Panel(new Rect(198,y+48,274,72));if(!string.IsNullOrEmpty(jobs.VisibleCareDialogue))DrawCareMessage(new Rect(210,y+55,250,58),message);else {GUI.Label(new Rect(210,y+55,250,58),message,new GUIStyle(DrivingHudArt.Text(16,CasualUI.Ink,true)){wordWrap=true});}Label(new Rect(202,y+127,270,26),occupied?"만족도 "+score.value+" · 요구 "+score.required:jobs.Active?"만족도 · 탑승 후 표시":"승객 없음",16,occupied?DrivingHudArt.Lime:DrivingHudArt.Light,true);DrivingHudArt.Meter(new Rect(202,y+158,270,10),occupied?score.value:0,DrivingHudArt.Lime);if(occupied){DrivingHudArt.Flat(new Rect(202+270*Mathf.Clamp01(score.required/100f)-1,y+155,2,16),Color.white);Label(new Rect(202,y+177,270,22),"승차 "+score.start+" · 청결 +"+score.clean,12,DrivingHudArt.Light);}
 }
